def verify_doi(self, doi: str) -> VerifyResult:
    """Verify a DOI via CrossRef API."""
    clean_doi = doi.strip()
    data = self._get(f"https://api.crossref.org/works/{quote(clean_doi, safe='')}")
    if data is None:
        return VerifyResult(valid=False, error="DOI not found or API error")
